// D+14 compliance report — normalisation, indicators and formatting.
// All the presentation is centralised here: the downstream email nodes only
// consume `email_subject` and `email_html`. A 40-line expression inside a
// "subject" field is neither readable nor editable by the business.

const p = $('NetVerify parameters').first().json;
const src = $input.first().json || {};

// The messages come from the database (typed by a technician): they are
// escaped before being injected into HTML.
const esc = (v) => String(v ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

const anomalies = Array.isArray(src.anomalies) ? src.anomalies : [];
const nbAnomalies = Number(src.nb_anomalies ?? anomalies.length) || 0;
const nbConformes = Number(src.nb_conformes ?? 0) || 0;
const nbSansMesure = Number(src.nb_sans_mesure ?? 0) || 0;
const nbVerified = nbAnomalies + nbConformes + nbSansMesure;

// Lines with no NetScan measurement are neither compliant nor at fault:
// counting them in the denominator would sink the rate because of a probe gap,
// not because of a service defect.
const base = nbAnomalies + nbConformes;
const complianceRate = base ? Math.round((nbConformes / base) * 1000) / 10 : 100;

const RANK = { high: 0, medium: 1, low: 2 };
const sorted = [...anomalies].sort((a, b) => (RANK[a.urgence] ?? 9) - (RANK[b.urgence] ?? 9));

const byUrgency = { high: 0, medium: 0, low: 0 };
for (const a of anomalies) { if (a.urgence in byUrgency) byUrgency[a.urgence] += 1; }

// The technology is carried by the prefix of ref_demande (e.g. ADSL/2026/15004).
const byTechnology = {};
for (const a of anomalies) {
  const t = String(a.ref_demande || '').split('/')[0].trim().toUpperCase() || 'UNKNOWN';
  byTechnology[t] = (byTechnology[t] || 0) + 1;
}

const level = byUrgency.high > 0 ? 'CRITICAL' : (nbAnomalies > 0 ? 'ALERT' : 'COMPLIANT');
const tint = { CRITICAL: '#c0392b', ALERT: '#e67e22', COMPLIANT: '#1e8449' }[level];
const bullet = { CRITICAL: '\u{1F6A8}', ALERT: '\u26A0\uFE0F', COMPLIANT: '\u2705' }[level];

const delay = p.verification_delay_days ?? 14;
const stamp = $now.setZone(p.timezone || 'Africa/Tunis').toFormat('dd/MM/yyyy \u00E0 HH:mm');
const trigger = p.origin_label || 'automatic execution';

const urgencyColour = { high: '#c0392b', medium: '#e67e22', low: '#7f8c8d' };
const cap = Number(p.max_email_rows) || 25;
const shown = sorted.slice(0, cap);
const hidden = sorted.length - shown.length;

const kpi = (value, label) => `<td align="center" width="25%" style="padding:14px 6px;border:1px solid #e5e8ec;background:#fafbfc"><div style="font:700 24px/1 Arial,Helvetica,sans-serif;color:#1f2933">${value}</div><div style="font:400 11px/1.5 Arial,Helvetica,sans-serif;color:#6b7580;text-transform:uppercase;letter-spacing:.6px;margin-top:5px">${label}</div></td>`;

const th = (label) => `<th align="left" style="padding:10px;font:700 11px/1.5 Arial,Helvetica,sans-serif;color:#6b7580;text-transform:uppercase;letter-spacing:.6px;border-bottom:1px solid #e5e8ec">${label}</th>`;
const td = (content, extra) => `<td style="padding:9px 10px;border-bottom:1px solid #eceff2;font:400 12px/1.6 Arial,Helvetica,sans-serif;color:#1f2933;${extra || ''}">${content}</td>`;

const rows = shown.map((a) => `<tr>${td(esc(a.ref_demande), 'white-space:nowrap')}${td(esc(a.num_appel), 'white-space:nowrap')}<td style="padding:9px 10px;border-bottom:1px solid #eceff2;font:700 11px/1.6 Arial,Helvetica,sans-serif;text-transform:uppercase;white-space:nowrap;color:${urgencyColour[a.urgence] || '#7f8c8d'}">${esc(a.urgence)}</td>${td(esc(a.message), 'color:#4a5560')}</tr>`).join('');

const breakdown = Object.entries(byTechnology).sort((a, b) => b[1] - a[1]).map(([t, n]) => `${esc(t)} : ${n}`).join(' &nbsp;&middot;&nbsp; ') || '\u2014';

const body = nbAnomalies > 0
  ? `<div style="font:700 12px/1.5 Arial,Helvetica,sans-serif;color:#1f2933;margin:22px 0 4px">Detail of the gaps</div><div style="font:400 12px/1.6 Arial,Helvetica,sans-serif;color:#6b7580;margin-bottom:10px">Urgency: <b style="color:${urgencyColour.high}">${byUrgency.high} high</b> &nbsp;&middot;&nbsp; <b style="color:${urgencyColour.medium}">${byUrgency.medium} medium</b> &nbsp;&middot;&nbsp; ${byUrgency.low} low<br>Technologies: ${breakdown}</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #e5e8ec"><thead><tr style="background:#f4f6f8">${th('Reference')}${th('Customer')}${th('Urgency')}${th('Diagnosis')}</tr></thead><tbody>${rows}</tbody></table>${hidden > 0 ? `<div style="font:400 12px/1.6 Arial,Helvetica,sans-serif;color:#6b7580;margin-top:10px">+ ${hidden} further anomaly(ies) not listed here &mdash; the full detail is in the follow-up journal of the dashboard.</div>` : ''}`
  : `<div style="margin:22px 0 4px;padding:16px;border:1px solid #d4e8da;background:#f2f9f4;font:400 13px/1.7 Arial,Helvetica,sans-serif;color:#1e5631">No rate gap detected on the interventions closed more than ${delay} days ago. The measured rates match the subscribed profile.</div>`;

const html = `<div style="background:#f0f2f5;padding:24px 0;font-family:Arial,Helvetica,sans-serif"><table role="presentation" align="center" width="680" cellpadding="0" cellspacing="0" style="width:680px;max-width:100%;border-collapse:collapse;background:#ffffff;border:1px solid #e0e4e8"><tr><td style="background:${tint};padding:18px 24px"><div style="font:700 17px/1.35 Arial,Helvetica,sans-serif;color:#ffffff">${bullet} NetVerify &mdash; D+${delay} compliance control</div><div style="font:400 12px/1.6 Arial,Helvetica,sans-serif;color:#ffffff;opacity:.85;margin-top:4px">Tunisie Telecom &nbsp;&middot;&nbsp; ${stamp} &nbsp;&middot;&nbsp; ${trigger}</div></td></tr><tr><td style="padding:22px 24px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse"><tr>${kpi(nbVerified, 'Verified')}${kpi(nbConformes, 'Compliant')}${kpi(nbAnomalies, 'Anomalies')}${kpi(complianceRate + ' %', 'Compliance rate')}</tr></table>${nbSansMesure > 0 ? `<div style="font:400 12px/1.6 Arial,Helvetica,sans-serif;color:#8a6d3b;background:#fcf8e3;border:1px solid #f2e3b3;padding:10px 12px;margin-top:14px">${nbSansMesure} work order(s) with no usable NetScan measurement: they are excluded from the compliance rate and need to be probed.</div>` : ''}${body}</td></tr><tr><td style="padding:0 24px 20px"><div style="border-top:1px solid #eceff2;padding-top:14px;font:400 11px/1.6 Arial,Helvetica,sans-serif;color:#96a0aa">Automatic message from the n8n workflow &laquo; NetVerify &mdash; D+${delay} compliance control &raquo;. Comparison of the measured rate with the subscribed rate, 10 % tolerance, on the interventions in state &laquo; Traite &raquo; for more than ${delay} days.</div></td></tr></table></div>`;

const subject = nbAnomalies > 0
  ? `${bullet} NetVerify \u2014 ${nbAnomalies} D+${delay} anomaly(ies)${byUrgency.high > 0 ? ` including ${byUrgency.high} critical` : ''} \u2014 ${stamp}`
  : `\u2705 NetVerify \u2014 D+${delay} control compliant (${nbVerified} verified) \u2014 ${stamp}`;

const summary = nbAnomalies > 0
  ? `${nbAnomalies} anomaly(ies) out of ${nbVerified} work order(s) verified \u2014 compliance rate ${complianceRate} %.`
  : `${nbVerified} work order(s) verified, no anomaly.`;

return [{
  json: {
    status: 'success',
    origin: p.origin,
    level,
    stamp,
    // Contract expected by the Streamlit dashboard: nb_anomalies / nb_conformes
    // / nb_sans_mesure, otherwise it falls back on `message`.
    nb_anomalies: nbAnomalies,
    nb_conformes: nbConformes,
    nb_sans_mesure: nbSansMesure,
    nb_verified: nbVerified,
    compliance_rate: complianceRate,
    by_urgency: byUrgency,
    by_technology: byTechnology,
    anomalies: sorted,
    email_subject: subject,
    email_html: html,
    response: {
      status: 'success',
      message: summary,
      level,
      nb_anomalies: nbAnomalies,
      nb_conformes: nbConformes,
      nb_sans_mesure: nbSansMesure,
      compliance_rate: complianceRate,
      anomalies: sorted,
    },
  },
}];
